-- Propósito: tablas del módulo enrollment (dueño único): participants, courses, enrollments.
-- SQL estándar: debe correr igual en PostgreSQL y en H2. Nada de SERIAL, UUID nativo ni funciones propias.
--
-- Pasos a implementar:
--   1. participants:
--        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
--        email VARCHAR(320) NOT NULL UNIQUE,
--        full_name VARCHAR(200) NOT NULL,
--        external_id VARCHAR(100)                      -- documento o código institucional, opcional
--   2. courses:
--        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
--        code VARCHAR(50) NOT NULL,
--        group_code VARCHAR(50) NOT NULL,             -- "group" es palabra reservada
--        name VARCHAR(200) NOT NULL,
--        instructor_email VARCHAR(320) NOT NULL,
--        CONSTRAINT uq_courses_code_group UNIQUE (code, group_code)
--   3. enrollments:
--        participant_id BIGINT NOT NULL REFERENCES participants(id),
--        course_id BIGINT NOT NULL REFERENCES courses(id),
--        PRIMARY KEY (participant_id, course_id)
--   4. Índice en courses(instructor_email) para "mis cursos".
--   5. Guardar correos siempre en minúsculas (lo hace la aplicación).

CREATE TABLE participants (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email VARCHAR(320) NOT NULL UNIQUE,
    full_name VARCHAR(200) NOT NULL,
    external_id VARCHAR(100)
);

CREATE TABLE courses (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL,
    group_code VARCHAR(50) NOT NULL,
    name VARCHAR(200) NOT NULL,
    instructor_email VARCHAR(320) NOT NULL,
    CONSTRAINT uq_courses_code_group UNIQUE (code, group_code)
);

CREATE TABLE enrollments (
    participant_id BIGINT NOT NULL REFERENCES participants(id),
    course_id BIGINT NOT NULL REFERENCES courses(id),
    PRIMARY KEY (participant_id, course_id)
);

CREATE INDEX idx_courses_instructor_email ON courses (instructor_email);
